# Compatibilidad con identificadores antiguos p01-p83: los perfiles actuales usan nombres legibles.
_PLANT_ORDER=list(PLANTS.keys())
def _v(value,lang="es",default=""):
    if isinstance(value,dict):return str(value.get(lang,value.get("es",default)) or default)
    return str(value if value is not None else default)
def _valid_lang(lang):return lang if lang in LANGUAGES else "es"
def _public_plant(p,lang="es"):
    lang=_valid_lang(lang)
    return {"id":p["id"],"plant_id":p["id"],"name":p["name"][lang],"scientific_name":p["scientific_name"],"scientific":p["scientific_name"],"group":p["group"],"description":p["description"][lang],"characteristics":p["characteristics"][lang],"identification":p["identification"][lang],"habitat":p["habitat"][lang],"pot_suitability":p["pot_suitability"][lang],"care":p["care"][lang],"curiosity":p["curiosity"][lang],"traditional_context":p["traditional_context"][lang],"traditional":p["traditional_context"][lang],"wellness_relation":p["wellness_relation"][lang],"observation":p["observation"][lang],"activity":p["activity"][lang],"precautions":p["precautions"][lang],"caution":p["precautions"][lang],"photo_search_terms":p["photo_search_terms"][lang],"photo_source":p["photo_source"],"disclaimer":p["disclaimer"][lang]}
def get_plant(plant_id,lang="es"):
    lang=_valid_lang(lang)
    pid=str(plant_id or "").strip().lower()
    if pid.startswith("plant_"):pid=pid[6:]
    if pid.startswith("p") and pid[1:].isdigit():
        n=int(pid[1:])
        pid=_PLANT_ORDER[n-1] if 1<=n<=len(_PLANT_ORDER) else ""
    p=PLANTS.get(pid)
    return _public_plant(p,lang) if p else None

