def _public_activity(a,lang="es"):
    lang=_valid_lang(lang)
    p=PLANTS.get(a.get("plant_id")) if a.get("plant_id") else None
    result={"id":a["id"],"section":a["section"],"title":_v(a["title"],lang),"description":_v(a["description"],lang),"minutes":a.get("minutes",3),"steps":a.get("steps",{}).get(lang,a.get("steps",{}).get("es",[])),"icon":a.get("icon","🍃")}
    if p:
        result["plant_id"]=p["id"]
        result["plant"]={"id":p["id"],"scientific":p["scientific_name"],"scientific_name":p["scientific_name"],"traditional":p["traditional_context"][lang],"activity":p["activity"][lang],"caution":p["precautions"][lang],"photo_search_terms":p["photo_search_terms"][lang]}
    return result
def get_activities(lang="es",section="all"):
    lang=_valid_lang(lang)
    if section not in ("all","plants","movement","calm","coach"):section="all"
    return [_public_activity(a,lang) for a in _CATALOG if section=="all" or a["section"]==section]
def get_activity(activity_id,lang="es"):
    a=_BY_ID.get(str(activity_id or ""))
    return _public_activity(a,lang) if a else None
def _section_for_kind(kind):
    return {"pause":"calm","energy":"movement","calm":"calm","nature":"plants","plants":"plants","coach":"coach","program":"all"}.get(kind,kind if kind in ("plants","movement","calm","coach") else "calm")
def _duration(minutes):
    try:n=int(minutes)
    except (TypeError,ValueError):n=3
    return min(MINUTES_ALLOWED,key=lambda x:abs(x-n))
def get_session(activity_id=None,minutes=3,lang="es",activity=None,kind=None):
    # Compatibilidad con main.py: get_session(lang, kind, minutes).
    if activity_id in LANGUAGES and isinstance(minutes,str) and str(lang).isdigit():
        old_lang,old_kind,old_minutes=activity_id,minutes,int(lang)
        lang,kind,minutes=old_lang,old_kind,old_minutes
        activity_id=None
    lang=_valid_lang(lang)
    if isinstance(activity,dict) and activity.get("id"):activity_id=activity["id"]
    a=_BY_ID.get(str(activity_id or ""))
    if not a:
        section=_section_for_kind(kind or "calm")
        pool=[x for x in _CATALOG if section=="all" or x["section"]==section]
        if not pool:pool=[x for x in _CATALOG if x["section"]=="calm"]
        a=random.choice(pool)
    result=_public_activity(a,lang)
    result.update({"minutes":_duration(minutes),"duration_seconds":_duration(minutes)*60,"session_id":create_session_id(),"language":lang,"disclaimer":DISCLAIMER[lang]})
    return result
