def get_program_day(lang="es",day=1):
    lang=_valid_lang(lang)
    try:day=max(1,min(7,int(day)))
    except (ValueError,TypeError):day=1
    item=_PROGRAM[day-1]
    title=item[0] if lang=="es" else item[1]
    goal=item[2] if lang=="es" else item[3]
    pool=[a for a in _CATALOG if a["section"]==item[4]]
    if item[4]=="plants" and day==3:pool=[_BY_ID["plant_mint"],_BY_ID["plant_chamomile"],_BY_ID["plant_rosemary"]]+pool
    activity=_public_activity(pool[(day-1)%len(pool)],lang)
    return {"day":day,"title":title,"goal":goal,"description":goal,"minutes":3+(day%3)*2,"activity":activity,"language":lang}
def get_health():
    return {"status":"ok","app":APP_NAME,"version":VERSION,"plants":len(PLANTS),"activities":len(_CATALOG)}
def get_config():
    return {"name":APP_NAME,"version":VERSION,"audience":"40+","languages":list(LANGUAGES),"durations":list(MINUTES_ALLOWED),"program_days":7,"sections":get_catalog(),"activity_count":len(_CATALOG),"plant_count":len(PLANTS)}
def create_session_id():
    return uuid.uuid4().hex
